CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_concession]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_concession]
	(
		[apuk_concessionid],
		[apuk_concessiontypeid],
		[apuk_concessiontypeid_entitytype],
		[apuk_concessiontypeidname],
		[apuk_dualmembership],
		[apuk_dualmembershipfirmid],
		[apuk_dualmembershipfirmid_entitytype],
		[apuk_dualmembershipfirmidname],
		[apuk_dualmembershipfirmidyominame],
		[apuk_enddate],
		[apuk_name],
		[apuk_ricsrecordid],
		[apuk_ricsrecordid_entitytype],
		[apuk_ricsrecordidname],
		[apuk_startdate],
		[apuk_subscriptionyear],
		[apuk_subsonlineupdate],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_concessionid],
		stg.[apuk_concessiontypeid],
		stg.[apuk_concessiontypeid_entitytype],
		stg.[apuk_concessiontypeidname],
		stg.[apuk_dualmembership],
		stg.[apuk_dualmembershipfirmid],
		stg.[apuk_dualmembershipfirmid_entitytype],
		stg.[apuk_dualmembershipfirmidname],
		stg.[apuk_dualmembershipfirmidyominame],
		stg.[apuk_enddate],
		stg.[apuk_name],
		stg.[apuk_ricsrecordid],
		stg.[apuk_ricsrecordid_entitytype],
		stg.[apuk_ricsrecordidname],
		stg.[apuk_startdate],
		stg.[apuk_subscriptionyear],
		stg.[apuk_subsonlineupdate],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_concession] stg
		LEFT JOIN [synapse_ce].[apuk_concession] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
